body:
Seems to be working as expected and code make sense. Needs rebase.

I would add support for remove/clean as well for consistency, nothing of this is strictly necessary and won't be called in normal conditions, but in case something will change in the future (or someone is using custom patching system).
```diff
diff --git a/core/io/resource_uid.cpp b/core/io/resource_uid.cpp
index 0e92805a6a..a2e72abc76 100644
--- a/core/io/resource_uid.cpp
+++ b/core/io/resource_uid.cpp
@@ -218,6 +218,9 @@ ResourceUID::ID ResourceUID::get_path_id(const String &p_path) const {
 void ResourceUID::remove_id(ID p_id) {
        MutexLock l(mutex);
        ERR_FAIL_COND(!unique_ids.has(p_id));
+       if (use_reverse_cache) {
+               reverse_cache.erase(unique_ids[p_id].cs);
+       }
        unique_ids.erase(p_id);
 }

@@ -279,6 +282,9 @@ Error ResourceUID::load_from_cache(bool p_reset) {

        MutexLock l(mutex);
        if (p_reset) {
+               if (use_reverse_cache) {
+                       reverse_cache.clear();
+               }
                unique_ids.clear();
        }

@@ -368,6 +374,9 @@ String ResourceUID::get_path_from_cache(Ref<FileAccess> &p_cache_file, const Str

 void ResourceUID::clear() {
        cache_entries = 0;
+       if (use_reverse_cache) {
+               reverse_cache.clear();
+       }
        unique_ids.clear();
        changed = false;
 }
```
